    'fc.help_body' => 'Διαχειρίζεται τους σύντομους κωδικούς που πληκτρολογούνται από το τηλέφωνο (όπως <code>*78</code>): Μην ενοχλείτε (DND), Προώθηση κλήσεων, Ομαδική/Κατευθυνόμενη ανάληψη κλήσης, Παρακολούθηση κλήσης, Σύνδεση/Αποσύνδεση από ουρά (<code>*81&lt;queue id&gt;</code> / <code>*80&lt;queue id&gt;</code>), Παύση / Συνέχιση ουράς (<code>*22&lt;break id&gt;</code> / <code>*23</code>).',
    'fc.help_body2' => 'Για κάθε κωδικό μπορούν να αλλάξουν ο <strong>κωδικός</strong> (οι κανονικοί κωδικοί πρέπει να ξεκινούν με <code>*</code>, οι κωδικοί με μεταβλητή παράμετρο με <code>_*</code>) και <strong>ποιοι ρόλοι μπορούν να τον χρησιμοποιούν</strong> (κενό = όλοι). Η ίδια η συμπεριφορά (τι κάνει) είναι σταθερή — δεν μπορεί να προστεθεί νέος τύπος συμπεριφοράς, μόνο αυτοί οι κωδικοί μπορούν να επεξεργαστούν.',
