    'cdr_reports.help_body' => 'Παρέχει λεπτομερές αρχείο στοιχείων κλήσεων (CDR) για όλες τις εισερχόμενες/εξερχόμενες κλήσεις που πραγματοποιούνται μέσω του AI PBX και του τηλεφωνικού κέντρου.',
    'cdr_reports.help_body2' => 'Κάθε γραμμή είναι μία κλήση: στο <b>Καλών</b> φαίνεται το trunk από το οποίο εισήλθε, στο <b>Καλούμενος</b> η δρομολόγηση και, εάν η κλήση εξήλθε από το PBX, το trunk και ο αριθμός που στάλθηκε· το <b>Απάντησε</b> είναι το εσωτερικό που δέχτηκε την κλήση. <b>Κατεύθυνση</b>: Εισερχόμενη, Εξερχόμενη, Εσωτερική ή Trunk σε trunk (εισήλθε από ένα trunk και εξήλθε από άλλο χωρίς να απαντήσει εσωτερικό του AiPBX). Αναπτύξτε μια γραμμή για να δείτε τη διαδρομή των μεταφερμένων κλήσεων. Φιλτράρετε κατά ημερομηνία, κατάσταση, εσωτερικό, συσκευή, κατεύθυνση και trunk· ακούστε ή κατεβάστε ηχογραφήσεις.',
