    'asterisk_settings.rtp_section_title' => 'Ρυθμίσεις RTP (μέσων)',
    'asterisk_settings.rtp_help_body' => 'Ελέγχει ποιο εύρος θυρών μεταφέρει τον ήχο (RTP) και εάν το Asterisk απορρίπτει ήχο που φτάνει από μη αναμενόμενη πηγή. Το αρχείο αυτό (<code>/etc/asterisk/rtp.conf</code>) δημιουργείται πλέον από τον πίνακα· οι χειροκίνητες αλλαγές στον διακομιστή χάνονται στην επόμενη «Εφαρμογή».',
    'asterisk_settings.field_rtp_start' => 'Θύρα έναρξης RTP',
    'asterisk_settings.rtp_start_help' => 'Αρχή του εύρους θυρών που δεσμεύεται για ροές ήχου. Κάθε ταυτόχρονη κλήση καταναλώνει θύρες από αυτό το εύρος.',
    'asterisk_settings.field_rtp_end' => 'Θύρα λήξης RTP',
    'asterisk_settings.rtp_end_help' => 'Τέλος του εύρους. Το coturn (αναμετάδοση TURN) χρησιμοποιεί τις 13479-14999 — μια επικάλυψη χαλάει τον ήχο του WebRTC και απορρίπτεται κατά την αποθήκευση.',
    'asterisk_settings.field_rtp_strict' => 'Αυστηρό RTP (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Όταν είναι ενεργό, το Asterisk απορρίπτει σιωπηλά τον ήχο που φτάνει από οποιαδήποτε πηγή εκτός από τη διεύθυνση/θύρα απομακρυσμένου άκρου που έχει μάθει (προστασία από επιθέσεις). Εάν το απομακρυσμένο PBX στέλνει μέσα από μη αναμενόμενη θύρα, αυτό προκαλεί σιωπηλό σφάλμα «χωρίς ήχο» χωρίς ίχνος στα αρχεία καταγραφής — μπορεί να απενεργοποιηθεί προσωρινά για διάγνωση.',
    'asterisk_settings.rtp_strict_yes' => 'Ενεργό (συνιστάται)',
    'asterisk_settings.rtp_strict_no' => 'Ανενεργό (για διάγνωση)',
    'asterisk_settings.rtp_restart_warning' => 'Η ρύθμιση Αυστηρό RTP τίθεται σε ισχύ με την «Εφαρμογή». Μια αλλαγή ΕΥΡΟΥΣ ΘΥΡΩΝ, ωστόσο, απαιτεί πλήρη επανεκκίνηση του Asterisk — το σύνολο θυρών δεσμεύεται μία φορά κατά τη φόρτωση της ενότητας.',
    'asterisk_settings.udptl_section_title' => 'Ρυθμίσεις T.38 UDPTL (μέσα φαξ)',
    'asterisk_settings.udptl_help_body' => 'Ορίζει τα εύρη θυρών UDP και τις παραμέτρους διόρθωσης σφαλμάτων προς τα εμπρός (FEC / Checksum) για τα πακέτα φαξ T.38 (UDPTL). Το αρχείο αυτό (<code>/etc/asterisk/udptl.conf</code>) διαχειρίζεται δυναμικά.',
    'asterisk_settings.field_udptl_start' => 'Θύρα έναρξης UDPTL',
