    'trunks.field_connection_mode' => 'Τρόπος σύνδεσης',
    'trunks.connection_mode_ip' => 'Βάσει IP (το απομακρυσμένο άκρο έχει στατική IP)',
    'trunks.connection_mode_register' => 'Εισερχόμενη εγγραφή (το απομακρυσμένο άκρο εγγράφεται σε εμάς)',
    'trunks.connection_mode_help' => 'Βάσει IP: το απομακρυσμένο άκρο αναγνωρίζεται από τη διεύθυνση IP του και η επαφή του διατηρείται στατική — ο συνιστώμενος τρόπος για άκρο με σταθερή IP στο ίδιο δίκτυο. Εισερχόμενη εγγραφή: το απομακρυσμένο άκρο μάς στέλνει SIP REGISTER και η διεύθυνσή του μαθαίνεται από αυτή την εγγραφή. Ο τρόπος αυτός απαιτεί όνομα χρήστη και κωδικό· το απομακρυσμένο άκρο πιστοποιεί με αυτά τόσο την εγγραφή όσο και τις κλήσεις του.',
    'trunks.connection_mode_warning' => 'Η μετάβαση σε τρόπο εγγραφής αφαιρεί τη στατική επαφή: δεν μπορούμε να καλέσουμε αυτό το trunk ΜΕΧΡΙ να εγγραφεί σε εμάς το απομακρυσμένο άκρο. Κάντε αυτή την αλλαγή σε συντονισμό με τη ρύθμιση εγγραφής στην πλευρά του απομακρυσμένου άκρου.',
