    'sound_packs.tab' => 'Πακέτα ήχων Asterisk',
    'sound_packs.title' => 'Επίσημα πακέτα ήχων Asterisk',
    'sound_packs.help_title' => 'Πακέτα ήχων Asterisk',
    'sound_packs.help_body' => 'Λαμβάνει και εγκαθιστά τα επίσημα μηνύματα συστήματος και τη μουσική αναμονής του Asterisk από το <code>downloads.asterisk.org</code>. Κάθε πακέτο είναι μία γλώσσα σε μία μορφή· το Asterisk αναπαράγει τη μορφή που αντιστοιχεί στο codec της κλήσης, διαφορετικά κάνει μετατροπή (g722 για G.722, ulaw/alaw για παρόχους).<br>- <strong>Core:</strong> μηνύματα συστήματος, ψηφία, φωνητικό ταχυδρομείο. <strong>Extra:</strong> πρόσθετα μηνύματα· πρέπει πρώτα να έχει εγκατασταθεί το πακέτο core της ίδιας γλώσσας.<br>- <strong>Μουσική αναμονής (opsound):</strong> εγκαθίσταται στο <code>/var/lib/asterisk/moh/opsound</code>· για να την αναπαράγετε, δημιουργήστε μια κλάση MOH με όνομα <strong>opsound</strong> στην καρτέλα Μουσική αναμονής.<br>- <strong>Türkçe (AiPBX):</strong> τα δικά τουρκικά μηνύματα του AiPBX (έκδοση GitHub, επαληθευμένα με SHA256)· η προεπιλεγμένη γλώσσα είναι τα τουρκικά, οπότε η αφαίρεσή τους σιγάζει τα μηνύματα συστήματος. Η αφαίρεση διαγράφει μόνο τα αρχεία που εγκατέστησε το πακέτο.',
