    'google_integration.guide_p2' => 'Όταν ο λογαριασμός Google του χρήστη ταιριάζει με την καταχωρισμένη διεύθυνση email στο AI PBX, ο έλεγχος ταυτότητας επιτυγχάνει και ο χρήστης ανακατευθύνεται στον εξουσιοδοτημένο πίνακα ελέγχου του.',
