    'system_update.help_body' => 'Η ενημέρωση δημιουργεί πρώτα αντίγραφο ασφαλείας της βάσης δεδομένων, των ρυθμίσεων και της διαμόρφωσης του Asterisk, έπειτα εγκαθιστά τη νέα έκδοση και ελέγχει ότι όλα λειτουργούν. Αν κάτι αποτύχει, επιστρέφει αυτόματα στην προηγούμενη έκδοση. Το Asterisk επανεκκινείται κατά την ενημέρωση: οι τρέχουσες κλήσεις διακόπτονται, γι\' αυτό δεν ξεκινά όσο υπάρχουν ενεργές κλήσεις. Μπορεί επίσης να εκτελεστεί στον διακομιστή: <code>sudo aipbx-update</code>',
