    'certificates.header_title' => 'Πιστοποιητικό TLS',
    'certificates.help_title' => 'Οδηγός πιστοποιητικών',
    'certificates.help_body' => 'Η πύλη (HTTPS), το WebRTC TURNS και το SIP-TLS/WSS χρησιμοποιούν κοινό πιστοποιητικό· οι αλλαγές εδώ εφαρμόζονται ταυτόχρονα σε Apache, coturn και Asterisk. Το <b>Let\'s Encrypt</b> είναι δωρεάν και ανανεώνεται αυτόματα· ο τομέας πρέπει να δείχνει σε αυτόν τον διακομιστή και η θύρα 80 πρέπει να είναι προσβάσιμη από το διαδίκτυο. Αν ο οργανισμός σας διαθέτει πιστοποιητικό, <b>ανεβάστε το</b> (PEM ή PFX)· τα ανεβασμένα πιστοποιητικά δεν ανανεώνονται αυτόματα, ανεβάστε νέο πριν λήξει. Με <b>αυτο-υπογεγραμμένο</b> πιστοποιητικό τα προγράμματα περιήγησης εμφανίζουν προειδοποίηση και το TURNS δεν λειτουργεί στα προγράμματα περιήγησης: οι κλήσεις WebRTC πίσω από τείχη προστασίας ενδέχεται να μην έχουν ήχο.',
