    'queue_reports.help_body' => 'Κάθε κλήση που εισέρχεται σε ουρά μετράται μία φορά. <b>Απαντημένες</b>: συνδέθηκαν με εκπρόσωπο. <b>Χαμένες</b>: ο καλών έκλεισε κατά την αναμονή ή έληξε ο χρόνος της ουράς. <b>Σύντομη εγκατάλειψη</b>: έκλεισε εντός %d δευτερολέπτων· εξαιρείται από το επίπεδο εξυπηρέτησης. <b>Επίπεδο εξυπηρέτησης</b>: κλήσεις που απαντήθηκαν εντός του στόχου, επί του συνόλου των κλήσεων εκτός των σύντομων εγκαταλείψεων. <b>ASA</b>: μέσος χρόνος αναμονής των απαντημένων κλήσεων. <b>AHT</b>: μέσος χρόνος ομιλίας. <b>Ποσοστό απάντησης</b> (εκπρόσωπος): πόσο συχνά ο εκπρόσωπος απάντησε όταν τον κάλεσε η ουρά. <b>Επανάκληση</b>: μια χαμένη κλήση θεωρείται επιλυμένη όταν ο αριθμός της κλήθηκε αργότερα από εσωτερικό ή κάλεσε ξανά και απαντήθηκε. Τα δεδομένα προέρχονται από το queue log του Asterisk· η αναφορά μπορεί να ληφθεί ως PDF ή Excel.',
