    'ai_models.help_title' => 'Μοντέλα AI σε αυτόν τον διακομιστή',
    'ai_models.help_body' => 'Εκτελεί μοντέλα AI στο ίδιο το PBX: το κείμενο και ο ήχος δεν εγκαταλείπουν ποτέ τον διακομιστή, και δεν υπάρχει κλειδί API ή κόστος. Πρώτα εγκαταστήστε το <strong>τοπικό περιβάλλον εκτέλεσης AI</strong> (περίπου 160 MB δίσκου, λαμβάνεται μία φορά), στη συνέχεια κατεβάστε τα μοντέλα που χρειάζεστε και αποδεχτείτε την άδειά τους. Ένα μοντέλο χρησιμοποιεί μνήμη και CPU ενώ είναι φορτωμένο· η δοκιμή ταχύτητας δείχνει αν είναι αρκετά γρήγορο σε αυτόν τον διακομιστή. Οι κλήσεις διατηρούν προτεραιότητα: η υπηρεσία εκτελείται με χαμηλότερη προτεραιότητα CPU και με όριο μνήμης. Δείτε docs/local-ai.md.',
