    'ai_apps.help_title' => 'Εφαρμογές AI με δικούς τους αριθμούς',
    'ai_apps.help_body' => 'Μια εφαρμογή AI απαντά σε μια κλήση, εκτελεί την εργασία της και μεταβιβάζει την κλήση σε έναν προορισμό. Δώστε της έναν εσωτερικό αριθμό για να την καλέσετε απευθείας, ή επιλέξτε την ως προορισμό σε IVR, εισερχόμενες δρομολογήσεις και χρονικές συνθήκες ("Εφαρμογή AI"). <strong>Ανακοίνωση με μεταβλητές</strong>: ένα κείμενο που διαβάζεται στον καλούντα από ένα φωνητικό μοντέλο αυτού του διακομιστή, με τιμές μέσα σε αυτό — τα {caller_number}, {caller_name}, {did} προέρχονται από την κλήση, οποιοδήποτε άλλο {name} από το δικό σας σύστημα μέσω της διεύθυνσης αναζήτησης. Οι αλλαγές τίθενται σε ισχύ με το <strong>Εφαρμογή</strong>.',
