    'ai_cloud.help_title' => 'Υπηρεσίες AI Cloud',
    'ai_cloud.help_body' => 'Λογαριασμοί παρόχων AI cloud σε ένα μέρος: ομιλία, ομιλία σε κείμενο, γλωσσικά μοντέλα (Gemini, Gemma, GPT, Llama …) και embeddings. Εισαγάγετε ένα κλειδί, δοκιμάστε το και επιλέξτε για κάθε εργασία και γλώσσα ποια μηχανή χρησιμοποιείται: ένα τοπικό μοντέλο αυτού του διακομιστή ή ένας πάροχος cloud. Τα δωρεάν πακέτα επισημαίνονται· η χρήση αυτού του μήνα εμφανίζεται σε κάθε πάροχο.',
