    'ai_tts.help_body' => 'Μετατρέπει κείμενο σε φυσική ομιλία με υπηρεσίες cloud (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Ακούστε το αποτέλεσμα, κατεβάστε το ως MP3 ή αποθηκεύστε το ως <b>ανακοίνωση</b> με ένα κλικ: μετατρέπεται στη μορφή του Asterisk (WAV 8 kHz) και προστίθεται στους Ήχους &amp; Ανακοινώσεις για IVR, διαδρομές εισερχομένων και χρονικές συνθήκες (τίθεται σε ισχύ μετά την Εφαρμογή). <b>Αυτές οι υπηρεσίες είναι επί πληρωμή</b> και χρεώνουν ανά χαρακτήρα· κάθε σύνθεση διατηρείται στο ιστορικό με το πλήθος χαρακτήρων της. Τα κλειδιά πρόσβασης προέρχονται από την κονσόλα κάθε παρόχου, αποθηκεύονται κρυπτογραφημένα και δεν εμφανίζονται ποτέ ξανά στη σελίδα.',
