    'push.help_title' => 'Σχετικά με την αρχιτεκτονική ειδοποιήσεων για κινητά',
    'push.help_intro' => 'Το softphone για κινητά του AI PBX διαθέτει <strong>πολυεπίπεδη αρχιτεκτονική ειδοποιήσεων</strong>:',
    'push.help_layer0' => '<strong>Επίπεδο 0 (χωρίς εξάρτηση - προεπιλογή):</strong> μόνιμη σύνδεση WSS, υπηρεσία προσκηνίου <code>specialUse</code> συμβατή με Android 15 και ένας ανθεκτικός στο Doze φύλακας <code>AlarmManager</code> που την επαναφέρει. Δεν απαιτείται εξωτερική υπηρεσία· οι κλήσεις φτάνουν ακόμη και όταν η συσκευή είναι αδρανής ή η οθόνη σβηστή.',
    'push.help_layer1' => '<strong>Επίπεδο 1 (προαιρετικό - Google FCM):</strong> επιπλέον εγγύηση αφύπνισης σε συσκευές κατασκευαστών με επιθετικούς περιορισμούς μπαταρίας (Xiaomi, Huawei...) ή όταν ο χρήστης έκλεισε την εφαρμογή με σάρωση. <em>Ενεργοποιείται μόνο όταν το εσωτερικό δεν έχει ενεργή καταχώριση SIP, επομένως τα καταχωρισμένα εσωτερικά δεν έχουν καμία καθυστέρηση.</em>',
    'push.help_no_fcm' => 'Αν δεν θέλετε FCM, αφήστε τον πάροχο ως <strong>«Τοπικό (χωρίς εξάρτηση)»</strong>. Τότε η εφαρμογή για κινητά δεν επικοινωνεί καθόλου με την Google μέσω δικτύου.',
