    'mailtpl.invite.body' => '<p>Γεια σας {name},</p>{mobile_section}<p>Ακολουθεί νέος σύνδεσμος για να ορίσετε τον κωδικό πρόσβασής σας στο <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Αν το κουμπί δεν λειτουργεί, ανοίξτε αυτόν τον σύνδεσμο: {reset_link}</p><p><em>Ο σύνδεσμος κωδικού ισχύει για 48 ώρες και λειτουργεί μία φορά. Αν δεν τον ζητήσατε, επικοινωνήστε με τον διαχειριστή του συστήματος.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Επαναφορά κωδικού πρόσβασης',
    'mailtpl.password_reset.body' => '<p>Γεια σας {name},</p><p>Ζητήθηκε επαναφορά του κωδικού πρόσβασης για τον λογαριασμό σας <strong>{username}</strong>.</p>{reset_button}<p>Αν το κουμπί δεν λειτουργεί, ανοίξτε αυτόν τον σύνδεσμο: {reset_link}</p><p><em>Ο σύνδεσμος ισχύει για 30 λεπτά. Αν δεν τον ζητήσατε, αγνοήστε αυτό το e-mail· ο κωδικός σας παραμένει ίδιος.</em></p>',
    'mailtpl.voicemail.subject' => 'Νέο φωνητικό μήνυμα από {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Γεια σας {name},</p><p>Έχετε νέο φωνητικό μήνυμα στη θυρίδα <strong>{mailbox}</strong>.</p><ul><li><strong>Από:</strong> {caller}</li><li><strong>Λήψη:</strong> {date}</li><li><strong>Διάρκεια:</strong> {duration}</li></ul><p>Αν η ηχογράφηση είναι συνημμένη, μπορείτε να την ακούσετε απευθείας εδώ. Μπορείτε επίσης να την ακούσετε στην πύλη ({portal_link}) ή καλώντας *97.</p>',
    'mailtpl.fax_received.subject' => 'Λήφθηκε νέο φαξ - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Λήφθηκε νέο φαξ.</p><ul><li><strong>Μονάδα:</strong> {department}</li><li><strong>Αριθμός φαξ:</strong> {did}</li><li><strong>Από:</strong> {caller}</li><li><strong>Σελίδες:</strong> {pages}</li><li><strong>Λήψη:</strong> {date}</li></ul><p>Το φαξ επισυνάπτεται ως PDF όταν αυτή η επιλογή είναι ενεργή. Όλα τα φαξ βρίσκονται στα εισερχόμενα φαξ: {portal_link}</p>',
    'mailtpl.fax_sent.subject' => 'Το φαξ παραδόθηκε στο {destination} (#{fax_id})',
    'mailtpl.fax_sent.body' => '<p>Το φαξ σας παραδόθηκε.</p><ul><li><strong>Προς:</strong> {destination}</li><li><strong>Σελίδες:</strong> {pages}</li><li><strong>Ώρα:</strong> {date}</li></ul><p>Απεσταλμένα φαξ: {portal_link}</p>',
    'mailtpl.fax_failed.subject' => 'Το φαξ ΔΕΝ παραδόθηκε στο {destination} (#{fax_id})',
    'mailtpl.fax_failed.body' => '<p>Το φαξ σας δεν μπόρεσε να παραδοθεί.</p><ul><li><strong>Προς:</strong> {destination}</li><li><strong>Σελίδες:</strong> {pages}</li><li><strong>Ώρα:</strong> {date}</li><li><strong>Αιτία:</strong> {error}</li></ul><p>Μπορείτε να το στείλετε ξανά από την πύλη: {portal_link}</p>',
    'mailtpl.test.subject' => 'Δοκιμαστικό e-mail {brand} ({date})',
    'mailtpl.test.body' => '<p>Αυτό είναι ένα δοκιμαστικό e-mail από το <strong>{brand}</strong>. Αν μπορείτε να το διαβάσετε, η αποστολή e-mail λειτουργεί.</p><ul><li><strong>Στάλθηκε:</strong> {date}</li><li><strong>Από:</strong> {from_name} &lt;{from_address}&gt;</li><li><strong>Προς:</strong> {to}</li><li><strong>Διακομιστής:</strong> {host}</li></ul>',
