    'storage.help_title' => 'Πού φυλάσσονται τα αρχεία συνομιλίας',
    'storage.help_body' => '<p>Τα συνημμένα συνομιλιών, οι μικρογραφίες τους και οι εικόνες ομάδων αποθηκεύονται από προεπιλογή στον δίσκο του διακομιστή (<code>/var/lib/aipbx/chat_files</code>). Με αποθηκευτικό χώρο συμβατό με S3 (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) πηγαίνουν αντί γι\' αυτό σε ένα bucket και τα μεγάλα αρχεία μένουν εκτός του PBX.</p><p>Οι λήψεις εξακολουθούν να περνούν από την υπηρεσία συνομιλίας, ώστε μόνο οι συμμετέχοντες μιας συνομιλίας να μπορούν να ανοίξουν τα αρχεία της· το bucket μπορεί να παραμείνει ιδιωτικό. Τα αρχεία που αποθηκεύτηκαν πριν από την αλλαγή εξυπηρετούνται ακόμη από τον δίσκο μέχρι να τα μετακινήσετε. Οι ρυθμίσεις του bucket ελέγχονται πριν αποθηκευτούν.</p><p>Οι ηχογραφήσεις κλήσεων, το φωνητικό ταχυδρομείο και τα φαξ παραμένουν στον τοπικό δίσκο.</p>',
