    'netsvc.help_title' => 'Υπηρεσίες δικτύου',
    'netsvc.help_body' => 'Τα επιτραπέζια τηλέφωνα βρίσκουν μόνα τους τον διακομιστή αυτόματης ρύθμισης όταν ο διακομιστής DHCP δίνει τη διεύθυνσή του (option 66). Τα DHCP και TFTP ενεργοποιούνται χωριστά. Με τον <strong>διακομιστή DHCP</strong> απενεργοποιημένο, παραμένει ο δικός σας διακομιστής DHCP: ορίστε εκεί τις επιλογές που αναφέρονται παρακάτω. Με αυτόν ενεργό, το AiPBX δίνει διευθύνσεις σε μία διεπαφή ή VLAN. Ο <strong>διακομιστής TFTP</strong> εξυπηρετεί τα αρχεία εκκίνησης και το firmware που ανεβάζετε. Η ρύθμιση κάθε τηλεφώνου (με τον κωδικό SIP) εξυπηρετείται πάντα μέσω HTTPS, ποτέ μέσω TFTP.',
