    'web_widgets.help_body' => 'Ένα widget προσθέτει ένα κουμπί «Καλέστε μας» σε οποιαδήποτε ιστοσελίδα. Οι επισκέπτες σας μιλούν από το πρόγραμμα περιήγησης μέσω WebRTC ή αφήνουν τον αριθμό τους και το PBX τους καλεί. Επικολλήστε τον κώδικα μίας γραμμής στην ιστοσελίδα (ή στο πρόσθετο WordPress) και πατήστε <strong>Εφαρμογή</strong> μετά την αποθήκευση.',
